"use strict";
// A Myers-style path list, as the diff package keeps it: each path starts
// with `lastComponent: undefined` and later holds a linked list of records,
// and a state object starts with `null` fields that later hold other values.
function addToPath(path, added, removed, oldPosInc) {
  var last = path.lastComponent;
  if (last && last.added === added && last.removed === removed) {
    return { oldPos: path.oldPos + oldPosInc, lastComponent: { count: last.count + 1, added: added, removed: removed, previousComponent: last.previousComponent } };
  }
  return { oldPos: path.oldPos + oldPosInc, lastComponent: { count: 1, added: added, removed: removed, previousComponent: last } };
}
function extractCommon(basePath, common) {
  if (common) basePath.lastComponent = { count: common, previousComponent: basePath.lastComponent, added: false, removed: false };
  basePath.oldPos += common;
}
function components(lastComponent) {
  var list = [];
  while (lastComponent) {
    list.push(lastComponent);
    var next = lastComponent.previousComponent;
    delete lastComponent.previousComponent;
    lastComponent = next;
  }
  return list.reverse();
}
function describe() {
  var bestPath = [{ oldPos: -1, lastComponent: undefined }];
  extractCommon(bestPath[0], 1);
  var path = addToPath(bestPath[0], false, true, 1);
  path = addToPath(path, true, false, 0);
  path = addToPath(path, true, false, 0);
  return components(path.lastComponent).map(function (c) {
    return (c.added ? "+" : c.removed ? "-" : "=") + c.count + ("previousComponent" in c ? "!" : "");
  }).join(" ");
}
function session() {
  var state = { user: null, retries: null, tags: undefined };
  state.user = { name: "ada" };
  state.retries = 3;
  state.tags = ["a", "b"];
  return state.user.name + " " + state.retries + " " + state.tags.join("+") + " " + JSON.stringify(state);
}
module.exports = { describe: describe, session: session };
